import type { VerifiedKuhsQuestion } from './verifiedQuestions';

type Kind = 'essay' | 'short-notes';
type Compact = [number, string, Kind, string, string];

function sourceRows(year: VerifiedKuhsQuestion['year'], subjectKey: string, pdfPage: number,
                    prefix: string, rows: Compact[]): VerifiedKuhsQuestion[] {
  return rows.map(([number, topicKey, kind, question, refs]) => ({
    id: `kuhs-${prefix}-p${pdfPage}-${String(number).padStart(2, '0')}`,
    year, subjectKey, pdfPage, topicKey, kind, question, examRefs: refs.split('|'),
  }));
}

